BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap;
SET LOCAL search_path=public,private,auth,extensions,pg_temp;
SELECT plan(33);
SELECT has_table('public','field_visits','Physical visit has tenant identity');
SELECT has_table('public','field_events','Field commands are append-only evidence');
SELECT has_table('public','field_incidents','Post-sale case retains the source');
SELECT has_table('public','field_assets','Private photo/signature/act identity');
SELECT has_table('public','field_receipts','Lost response has a durable receipt');
SELECT ok((SELECT bool_and(relrowsecurity) FROM pg_class WHERE oid=ANY(ARRAY['public.field_visits'::regclass,'public.field_events'::regclass,'public.field_incidents'::regclass,'public.field_assets'::regclass,'public.field_receipts'::regclass])),'Every field table enforces RLS');
SELECT col_not_null('public','field_visits','org_id','Visit requires tenant');
SELECT col_not_null('public','field_visits','assigned_to','Visit has a responsible actor');
SELECT col_not_null('public','field_events','org_id','Command requires tenant');
SELECT col_not_null('public','field_incidents','org_id','Incident requires tenant');
SELECT col_not_null('public','field_assets','org_id','Evidence requires tenant');
SELECT col_not_null('public','field_receipts','org_id','Receipt requires tenant');
SELECT ok(NOT has_table_privilege('anon','public.field_visits','SELECT'),'Anonymous has no agenda');
SELECT ok(NOT has_table_privilege('anon','public.field_assets','SELECT'),'Anonymous has no personal evidence');
SELECT ok(NOT has_table_privilege('authenticated','public.field_events','INSERT'),'Browser cannot forge evidence directly');
SELECT ok(NOT has_table_privilege('authenticated','public.field_incidents','UPDATE'),'Browser cannot rewrite the source');
SELECT ok(NOT has_table_privilege('documentary_backend','public.field_events','UPDATE'),'HTTP edge cannot edit the audit');
SELECT ok(NOT has_table_privilege('documentary_backend','public.field_assets','DELETE'),'HTTP edge cannot erase acta');
SELECT ok(NOT has_table_privilege('documentary_backend','public.field_receipts','UPDATE'),'HTTP edge cannot rewrite receipts');
SELECT ok(NOT has_function_privilege('anon','private.field_next_code(uuid,text,uuid)','EXECUTE'),'No anonymous tenant sequence');
SELECT ok(NOT has_function_privilege('authenticated','private.field_next_code(uuid,text,uuid)','EXECUTE'),'Assignment sequence is backend-only');
SELECT ok(has_function_privilege('documentary_backend','private.field_next_code(uuid,text,uuid)','EXECUTE'),'HTTP edge uses a tenant-wide guarded sequence');
SELECT ok(NOT has_function_privilege('authenticated','private.field_actor_role(uuid,uuid)','EXECUTE'),'Live actor lock is backend-only');
SELECT ok(NOT has_function_privilege('anon','private.field_people(uuid)','EXECUTE'),'No anonymous personnel directory');
SELECT is((SELECT count(*)::integer FROM pg_trigger WHERE tgname='field_no_truncate' AND NOT tgisinternal),5,'Every contextual field fact resists TRUNCATE');
SELECT is((SELECT count(*)::integer FROM pg_trigger WHERE tgname='field_unit_context' AND NOT tgisinternal),2,'Photos and incidents must target a sealed unit');
SELECT is((SELECT count(*)::integer FROM pg_trigger WHERE tgname='field_immutable' AND NOT tgisinternal),3,'Act, receipt and event have immutable triggers');
SELECT ok(position('current_user_org_ids' in pg_get_functiondef('private.field_access(uuid,uuid)'::regprocedure))>0,'Assignment respects live tenant assurance');
SELECT has_table('public','field_purchase_authorizations','Supplemental purchase requires distinct immutable authority');
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='public.field_purchase_authorizations'::regclass),'Loss authority enforces RLS');
SELECT ok(NOT has_table_privilege('authenticated','public.field_purchase_authorizations','SELECT'),'Installer cannot read purchasing authority');
SELECT is((SELECT count(*)::integer FROM pg_trigger WHERE tgname IN('field_loss_immutable','field_loss_no_truncate') AND NOT tgisinternal),2,'Supplemental authority resists edits, deletion and truncate');
SELECT ok(position('field_authorization_id IS NULL' in pg_get_functiondef('private.purchase_quantity_capacity()'::regprocedure))>0,'Original capacity excludes supplemental claims');
SELECT * FROM finish();
ROLLBACK;
